  mutate(continent = fct_reorder(continent, estimate)) |&gt;
  ggplot(aes(x = estimate, y = continent)) +
  stat_dist_halfeye(
    aes(dist = dist_normal(mu = estimate, sigma = std.error)),
    fill = "olivedrab"
  )




